export type User = {
	user_id: string,
	email: string,
	email_verified: boolean,
	display_name: string,
	display_name_slug: string,
	account_type: AccountType,
	subscription_tier: SubscriptionTier,
	created_at: string,
	updated_at: string,
	last_login_at: string,
	account_status: AccountStatus,
	locale: string,
	timezone: string | null,
	onboarding_complete: boolean,
	tos_accepted_at: string,
	tos_version: string,
	privacy_accepted_at: string,
	privacy_version: string,
	/**
	 *  Echo count limit override. 0 = use tier default from config.
	 *  Non-zero = hard override (e.g., admin grant, beta reward).
	 *  Reference: ME-UAD-001 §6.1.
	 */
	echo_count_limit?: number,
	/**
	 *  When true, this user's Echoes never interact with other users' Echoes.
	 *  Reference: ME-PDP-001 (cross-user consent), ME-UAD-001 §4.
	 */
	solo_mode?: boolean,
	/**
	 *  When set, account will be purged after this date (30-day grace period).
	 *  Reference: ME-PDP-001 §5.3, ME-UAD-001 §5.1.
	 */
	deletion_scheduled_at?: string | null,
	/**
	 *  CCPA "Do Not Sell My Personal Information" flag.
	 *  When true, analytics_opt_out is also true.
	 *  Reference: ME-PDP-001 §4.3.
	 */
	do_not_sell?: boolean,
	/**
	 *  When true, client-side analytics events are discarded.
	 *  Linked to do_not_sell per ME-PDP-001.
	 */
	analytics_opt_out?: boolean,
	/**
	 *  GDPR Art. 18 — Right to Restriction of Processing. When true, the
	 *  tick engine MUST skip every Echo owned by this user — no diary
	 *  generation, no relationship updates, no LLM calls. Distinct from
	 *  `solo_mode` (which only blocks cross-user interaction) and from
	 *  account deletion (data is preserved). Toggled via
	 *  POST /account/me/restrict-processing  +  /unrestrict-processing.
	 */
	processing_restricted?: boolean,
	/**
	 *  When the current paid subscription expires. None = Free tier (no expiry).
	 *  Crypto payments set this to `now + duration_days`. Extension adds to existing.
	 */
	subscription_expires_at?: string | null,
	// Stripe customer ID (cus_...). Populated on first Stripe checkout.
	stripe_customer_id?: string | null,
	// Stripe subscription ID (sub_...). Populated on checkout.session.completed.
	stripe_subscription_id?: string | null,
	/**
	 *  Public profile visibility — controls what other authenticated users see
	 *  at `GET /users/{user_id}`. Default `Public` on deserialisation for
	 *  accounts that predate this field. Reference: ME-API-001 §4.3.3.
	 */
	profile_visibility: ProfileVisibility,
	// Free-text bio surfaced on the public profile (max 500 chars).
	bio?: string | null,
	/**
	 *  Public avatar URL returned on profile and list endpoints. Populated by
	 *  `POST /account/me/profile/avatar`. None = default placeholder on client.
	 */
	avatar_url?: string | null,
};

